CREATE DATABASE IF NOT EXISTS banking_db CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE banking_db;
CREATE TABLE IF NOT EXISTS customers(customer_id BIGINT PRIMARY KEY AUTO_INCREMENT,full_name VARCHAR(120) NOT NULL,address VARCHAR(300) NOT NULL,mobile_number VARCHAR(24) NOT NULL,pin_hash VARCHAR(60) NOT NULL,created_at DATETIME NOT NULL,INDEX idx_customer_name(full_name)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS accounts(account_number VARCHAR(20) PRIMARY KEY,customer_id BIGINT NOT NULL,account_type ENUM('SAVINGS','CURRENT') NOT NULL,balance DECIMAL(15,2) NOT NULL DEFAULT 0.00 CHECK(balance>=0),status ENUM('ACTIVE','CLOSED') NOT NULL DEFAULT 'ACTIVE',opening_date DATE NOT NULL,daily_withdrawal_limit DECIMAL(15,2) NOT NULL DEFAULT 20000.00 CHECK(daily_withdrawal_limit>=0),FOREIGN KEY(customer_id) REFERENCES customers(customer_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS transactions(transaction_id CHAR(36) PRIMARY KEY,ledger_order BIGINT NOT NULL AUTO_INCREMENT UNIQUE,account_number VARCHAR(20) NOT NULL,transaction_type ENUM('OPENING','DEPOSIT','WITHDRAWAL','TRANSFER_IN','TRANSFER_OUT','INTEREST') NOT NULL,amount DECIMAL(15,2) NOT NULL CHECK(amount>0),transaction_timestamp DATETIME(6) NOT NULL,balance_after DECIMAL(15,2) NOT NULL CHECK(balance_after>=0),reference_number CHAR(36) NULL,FOREIGN KEY(account_number) REFERENCES accounts(account_number),INDEX idx_tx_account_date(account_number,transaction_timestamp),INDEX idx_tx_reference(reference_number)) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS administrators(administrator_id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(60) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL) ENGINE=InnoDB;
